 novelty=[claim('A capability-matched intervention: train one task and test the same skill on the other, rather than infer transfer from aggregate scores.',2,'Introduction'),claim('An empirical comparison of transfer across four degrees of architectural coupling.',5,'Fig. 1 & Table 1'),claim('Understanding-only post-training as a practical way to improve generation while limiting distribution shift.',8,'Sec. 4')],
 existing=claim('Existing UMMs, visual tokenizers, transformers, autoregressive/diffusion generation, and LoRA are experimental machinery. The paper does not introduce a new image generator or sampler.',5,'Sec. 3.1'),
 stages=[stage('Skill examples','Images and count questions','Build matched understanding and generation training tasks.','Test a specific capability rather than a broad benchmark average.','VQA targets / image-caption control pairs',5,'Sec. 3.1','Training data'),stage('Frozen visual pathway','Input image','Encode images using the chosen pretrained UMM.','Keep the non-transformer components fixed in the intervention.','Visual tokens',25,'Appendix A','Frozen'),stage('Adapt the backbone','Visual tokens and question','Train LoRA in attention Q/K/V and MLP layers.','Concentrate the intervention in the shared transformer.','Updated adapter parameters',25,'Appendix A','Trained'),stage('Cross-task test','Generation prompt','Generate with the adapted model without generation supervision in this run.','Measure whether understanding updates transfer.','Generated image',6,'Sec. 3.1','Inference'),stage('Capability evaluation','Generated images','Check object count, layout, or OCR output; also assess distribution shift.','Skill accuracy and visual preservation are different outcomes.','Accuracy / MAD / OCR and distribution metrics',9,'Secs. 4.1–4.3','Evaluation only')],
 training=[claim('Select a pretrained UMM; construct one capability-specific dataset per run.',25,'Appendix A'),claim('Train rank-128 LoRA on transformer Q/K/V and MLP layers with the understanding objective. Separate control runs use generation supervision.',25,'Appendix A'),claim('Image encoder, projector/aligner, language-model head and diffusion head stay frozen.',25,'Appendix A')],
 inference=[claim('Supply a text-to-image prompt to the adapted UMM and use its original generation mechanism.',6,'Sec. 3.1'),claim('No VQA answers or counting annotations are supplied to generation. Detectors/OCR are used afterwards for evaluation.',6,'Sec. 3.1; p. 11 Sec. 4.3')],
 results=[result('Counting accuracy (%)','GenEval-style count prompts, Lumina-DiMOO','Pretrained baseline',48,57,'up',8,'Table 2','Direct generation training also obtains 57%; the accuracy alone does not distinguish the two strategies.'),result('FID to baseline outputs','Counting prompts, Lumina-DiMOO','Direct generation training',52.51,31.47,'down',8,'Table 2; definition p. 9','This FID measures shift from baseline-generated images, not distance to a real-image dataset.','Understanding → generation'),result('Spatial accuracy (%)','Synthetic diagonal-relation prompts','Direct generation training',80,74,'up',10,'Table 3','Understanding transfer has lower task accuracy here, although its FID to baseline is slightly lower.','Understanding → generation')],
 limitations=[claim('Only four representative architectural families are tested in the main analysis; architecture alone does not explain the direction or strength of transfer.',42,'Appendix E','Authors’ limitation'),claim('Text transfer is weaker on several measures, and the best direction cannot yet be predicted in advance.',42,'Appendix E','Authors’ limitation')],
 equations=[],equationNote='This paper’s key contribution is an experimental intervention, not a new mathematical objective. Read the architecture comparison and the train → test controls first.',
 dimensions=[dim('training','Enabling setup','LoRA adapts only part of the model. No end-to-end training speedup is established by the transfer results.',25,'Appendix A'),dim('generalization','Primary contribution','Cross-task capability transfer and preservation of the baseline generation distribution.',8,'Table 2')],
 takeaway='Shared machinery can make understanding supervision useful for generation; the strength depends on the skill.',
 comparison=compare(domain=('General image understanding and generation',1,'Abstract'),architecture=('Four 7B–8B UMMs: Lumina-DiMOO, Janus-Pro, BAGEL, BLIP3-o',5,'Sec. 3.1'),objective=('Task-specific LoRA supervised fine-tuning; separate understanding and generation runs',25,'Appendix A'),generative=('Existing autoregressive and discrete/continuous diffusion UMMs',3,'Sec. 2.1'),flow=('Diffusion is part of existing UMMs; no new flow sampler',3,'Sec. 2.1'),frequency=('No wavelet method introduced',3,'Sec. 2.1'),trainingCost=('LoRA rank 128, frozen non-backbone components; speedup not reported',25,'Appendix A'),inferenceCost=('Original UMM generation procedure; inference speedup not reported',6,'Sec. 3.1'),supervision=('Counting VQA; synthetic spatial and rendered-text examples',9,'Secs. 4.2–4.3'),modality=('Not a medical-imaging study',1,'Abstract'),datasets=('PixMo-Points/Count; ImageNet-derived spatial pairs; rendered Markdown text',5,'Sec. 3.1; pp. 9, 11'),metrics=('Accuracy, MAD, IS, FID to baseline; OCR WER/CER and text metrics',8,'Tables 2–4')),
