 existing=claim('U-Net backbones, flow matching, Fisher-KPP-inspired dynamics, TV-L1 optical flow, and image warping are reused. The contribution is their disentangled forecasting formulation and projection regularizer.',9,'Sec. 3.2; p. 10 Implementation'),
 stages=[stage('Baseline + horizon','Baseline image, lesion mask, and elapsed time','Condition the morphology model on anatomy and the requested interval.','Forecast progression from a known observation.','Morphological velocity',8,'Eq. 14','Trained'),stage('Lesion evolution','Morphological velocity','Integrate over the time interval to predict the future lesion.','Separate structural evolution from appearance.','Predicted lesion mask',9,'Inference','Inference'),stage('Structural warp','Baseline and predicted lesion masks','Estimate TV-L1 displacement, then warp the baseline image.','Move the structure before changing signal intensity.','Morphology-warped MRI',9,'Eqs. 20–21','Nonlearned optical flow'),stage('Intensity refinement','Warped image and baseline lesion conditioning','Integrate the learned intensity velocity.','Capture signal changes that a spatial warp cannot express.','Refined future image',9,'Inference','Trained'),stage('Texture preservation','Baseline lesion texture and refined image','Add high-frequency guidance extracted using Difference-of-Gaussians.','Preserve lesion-specific texture details.','Final predicted MRI',22,'Appendix D','Inference')],
 training=[claim('Use longitudinal image/mask pairs and their time interval. Convert masks through signed distance and sigmoid to concentration proxies.',8,'Sec. 3.2; p. 10 map construction'),claim('Fit diffusion/reaction terms and estimate transport to form the physics span. Train morphology with flow matching plus λ times projection-residual loss.',6,'Sec. 3.1.2; p. 8 Eq. 17'),claim('Train intensity flow in image space with a flow-matching objective conditioned on lesion information.',8,'Sec. 3.2; p. 9 Eq. 19')],
 inference=[claim('Require the baseline lesion mask as well as the baseline image and time interval. Predict the evolved lesion, estimate optical flow, and warp the image.',9,'Inference'),claim('Refine intensity and preserve baseline lesion texture. The PDE loss and follow-up ground truth are not inference inputs.',9,'Inference; p. 22 Appendix D')],
 results=[result('DSC','UCSF tumor progression','T-UNet',0.728,0.752,'up',12,'Table 1','Lesion-level agreement improves; the same comparison has a lower image PSNR.'),result('PSNR (dB)','UCSF tumor progression','T-UNet',31.739,31.364,'up',12,'Table 1','A counter-result: better lesion progression does not imply better whole-image PSNR.'),result('DSC','LMSLS, PDE regularizer ablation','Without PDE loss',0.690,0.696,'up',14,'Table 3','The controlled gain from the regularizer is modest; do not attribute all performance to physics.')],
 limitations=[claim('Baseline lesion masks are required; segmentation errors can propagate into both predicted morphology and future images.',23,'Appendix E.1','Authors’ limitation'),claim('Two separate flow models add overhead; the physics currently guides learning through a regularizer.',23,'Appendix E.1','Authors’ limitation'),claim('LUMIERE full-model PSNR differs between Table 1 (37.216) and the joint row of Table 2 (37.075). The atlas does not silently merge these values.',12,'Table 1; Table 2 p. 13','Source inconsistency')],
 equations=[equation('The physics-inspired dynamics',r'\frac{\partial c}{\partial t}=D\Delta c+\rho c(1-c)-\mathbf u\cdot\nabla c',['c(x,t): normalized lesion concentration proxy; x: location; t: time','D: diffusion coefficient; Δ: spatial Laplacian','ρ: reaction/proliferation rate; u: advection velocity field','∇: spatial gradient; ·: dot product'],'Spread out, grow locally, and move through space. These are three different ways the concentration can change.','These terms define the physics span used by the regularizer; the paper does not solve an exact patient-specific biological model at deployment.',5,'Eq. 2'),equation('Penalize what the physics span cannot explain',r'\mathcal L_{\mathrm{PDE}}=\|v_\theta-\Pi_{\mathcal S}(v_\theta)\|_2^2',['vθ: predicted morphology velocity; θ: learned network parameters','S: span of Δc, c(1−c), and −u·∇c evaluated using baseline quantities','ΠS: least-squares projection onto that span','‖·‖₂²: squared Euclidean norm'],'Project the prediction onto the three physics-inspired components, then penalize the part left over.','This is a soft preference for physics-compatible motion, not an equality constraint requiring exact PDE solutions.',7,'Eq. 13')],
